  function readJson(key, fallback){
    try { var value = localStorage.getItem(key); if (value == null || value === "") return fallback; return JSON.parse(value); } catch(e) { return fallback; }
  }
  function writeJson(key, value){ localStorage.setItem(key, JSON.stringify(value)); }
  function localId(row){ return String(row && (row.local_id || row.id || "")).trim(); }
  function importarHistorial(){
    if (!window.localStorage || !ROWS.length) return;
    var existente = readJson("exc_agro_hist", []);
    if (!Array.isArray(existente)) existente = [];
    var marker = readJson(STORAGE_MARKER, null);
    var completos = ROWS.every(function(row){ var id = localId(row); return existente.some(function(item){ return item && localId(item) === id; }); });
    if (marker && marker.version === VERSION && completos) return;
    var ids = {}; ROWS.forEach(function(row){ ids[localId(row)] = true; });
    var limpio = existente.filter(function(item){ if (!item) return false; var id = localId(item); if (!id) return false; if (ids[id]) return false; return true; });
    var nuevos = ROWS.map(function(row){ var clone = JSON.parse(JSON.stringify(row)); clone.supabase_synced = false; clone.supabase_synced_at = ""; return clone; });
    writeJson("exc_agro_hist", limpio.concat(nuevos));
    writeJson(STORAGE_MARKER, { version: VERSION, registros: ROWS.length, dias: ["2025-08-08","2025-08-09"], fuente: SOURCE_FILES, aplicado_en: new Date().toISOString() });
    try { window.dispatchEvent(new CustomEvent("historial-ventas-importado", { detail: { registros: ROWS.length } })); } catch(e) {}
  }
  window.EXCOMERCAFE_HISTORIAL_VENTAS_20250808_20250809 = ROWS;
  window.aplicarHistorialVentas20250808_20250809 = importarHistorial;
  importarHistorial();
